// DeleteUniqueIndexCache 删除索引存在的缓存
func (w *WechatPayBillRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.WechatPayBill) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, w.cache.Key(CacheWechatPayBillByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[w.cache.Key(CacheWechatPayBillByIDPrefix, item.ID)] = struct{}{}
			KeyMap[w.cache.Key(CacheWechatPayBillByChannelOrderIDPrefix, item.ChannelOrderID)] = struct{}{}
			KeyMap[w.cache.Key(CacheWechatPayBillByTradeTimePrefix, item.TradeTime)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := w.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
